/* G2 Print Formats – G2 Technology corporate theme (#1551C3) */
.g2-print-format {
	font-family: Arial, Helvetica, sans-serif;
	font-size: 11px;
	color: #333;
	line-height: 1.45;
	position: relative;
	background: #fff;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
	color-adjust: exact;
}

.g2-print-format .g2-content {
	position: relative;
	z-index: 1;
}

.g2-print-format .g2-status-banner {
	text-align: center;
	font-weight: bold;
	color: #c0392b;
	margin: 6px 0 10px;
	font-size: 13px;
}

/* Header */
.g2-print-format .g2-header {
	display: flex;
	justify-content: space-between;
	align-items: flex-start;
	padding: 0 0 14px;
	border-bottom: 2px solid #1551C3;
	margin-bottom: 18px;
}

.g2-print-format .g2-header-left {
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	gap: 8px;
	flex: 1;
	min-width: 0;
	padding-right: 16px;
}

.g2-print-format .g2-logo-full {
	height: 64px;
	width: auto;
	max-width: 280px;
	object-fit: contain;
	object-position: left top;
	flex-shrink: 0;
	margin-top: 0;
}

.g2-print-format .g2-header-brand {
	width: 100%;
	max-width: 420px;
	padding-top: 0;
}

.g2-print-format .g2-contact-line {
	display: flex;
	align-items: flex-start;
	gap: 6px;
	font-size: 9px;
	color: #777;
	margin-bottom: 2px;
	line-height: 1.4;
}

.g2-print-format .g2-contact-line svg {
	width: 11px;
	height: 11px;
	flex-shrink: 0;
	margin-top: 1px;
	fill: #1551C3;
}

.g2-print-format .g2-doc-title-wrap {
	text-align: right;
	flex-shrink: 0;
	padding-top: 0;
}

.g2-print-format .g2-doc-title {
	font-size: 26px;
	font-weight: bold;
	color: #1551C3;
	margin: 0;
	letter-spacing: 0.5px;
	text-transform: uppercase;
}

.g2-print-format .g2-doc-number {
	margin-top: 4px;
	font-size: 12px;
	font-weight: bold;
	color: #000;
}

/* Order Details card */
.g2-print-format .g2-order-details {
	background: #f5f5f5;
	border: 1px solid #e8e8e8;
	border-radius: 6px;
	padding: 14px 16px;
	margin-bottom: 18px;
}

.g2-print-format .g2-order-details-body {
	display: flex;
	justify-content: space-between;
	gap: 24px;
	align-items: flex-start;
}

.g2-print-format .g2-party {
	flex: 1.1;
	min-width: 0;
}

.g2-print-format .g2-party-label {
	font-size: 8px;
	font-weight: bold;
	color: #5b7a9d;
	text-transform: uppercase;
	letter-spacing: 0.5px;
	margin-bottom: 6px;
}

.g2-print-format .g2-party-name {
	font-size: 12px;
	font-weight: bold;
	color: #000;
	margin-bottom: 4px;
}

.g2-print-format .g2-party-tax-id {
	font-size: 10px;
	color: #333;
	margin-bottom: 4px;
}

.g2-print-format .g2-party-address {
	font-size: 10px;
	color: #333;
	line-height: 1.5;
}

.g2-print-format .g2-meta-fields {
	flex: 1.2;
	min-width: 0;
}

.g2-print-format .g2-meta-grid {
	display: flex;
	flex-wrap: wrap;
	gap: 10px 20px;
}

.g2-print-format .g2-meta-item {
	width: calc(50% - 10px);
	box-sizing: border-box;
}

.g2-print-format .g2-meta-label {
	font-size: 8px;
	font-weight: bold;
	color: #5b7a9d;
	text-transform: uppercase;
	letter-spacing: 0.4px;
	margin-bottom: 2px;
}

.g2-print-format .g2-meta-value {
	font-size: 11px;
	font-weight: bold;
	color: #000;
	line-height: 1.3;
}

/* Items table */
.g2-print-format .g2-items-table {
	width: 100%;
	border-collapse: collapse;
	margin-top: 4px;
}

.g2-print-format .g2-items-table th {
	background-color: #1551C3 !important;
	background: #1551C3 !important;
	color: #ffffff !important;
	font-weight: bold;
	text-transform: uppercase;
	padding: 10px 8px;
	font-size: 9px;
	border: none;
	white-space: nowrap;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
	color-adjust: exact;
}

.g2-print-format .g2-items-table th,
.g2-print-format .g2-items-table th span,
.g2-print-format .g2-items-table th .g2-th-inner {
	color: #ffffff !important;
}

.g2-print-format .g2-items-table th .g2-th-inner {
	display: flex;
	align-items: center;
	gap: 4px;
	justify-content: flex-start;
}

.g2-print-format .g2-items-table th.text-right .g2-th-inner {
	justify-content: flex-end;
}

.g2-print-format .g2-items-table th.text-center .g2-th-inner {
	justify-content: center;
}

.g2-print-format .g2-items-table th svg {
	width: 11px;
	height: 11px;
	fill: #ffffff !important;
	flex-shrink: 0;
}

.g2-print-format .g2-items-table td {
	border: none;
	border-bottom: 1px solid #eee;
	padding: 10px 8px;
	background: #fff;
	font-size: 10px;
	vertical-align: top;
	color: #333;
}

.g2-print-format .g2-items-table th.text-right,
.g2-print-format .g2-items-table td.text-right {
	text-align: right;
}

.g2-print-format .g2-items-table th.text-center,
.g2-print-format .g2-items-table td.text-center {
	text-align: center;
}

.g2-print-format .g2-sl-no {
	font-weight: bold;
	color: #c9a227;
	font-size: 12px;
}

.g2-print-format .g2-item-name {
	font-weight: bold;
	color: #000;
	font-size: 11px;
}

.g2-print-format .g2-item-desc {
	display: block;
	margin-top: 2px;
	font-size: 9px;
	color: #555;
	font-weight: normal;
}

.g2-print-format .g2-qty {
	font-weight: bold;
	color: #333;
}

/* Totals above, then Terms + Bank aligned side by side */
.g2-print-format .g2-after-items {
	margin-top: 20px;
}

.g2-print-format .g2-totals-wrap {
	width: 280px;
	max-width: 45%;
	margin-left: auto;
	min-width: 220px;
}

.g2-print-format .g2-footer {
	display: flex;
	justify-content: space-between;
	align-items: stretch;
	margin-top: 16px;
	gap: 28px;
}

.g2-print-format .g2-terms {
	flex: 1.3;
	font-size: 9px;
	color: #333;
	line-height: 1.55;
	background: #f5f5f5;
	border: 1px solid #e0e0e0;
	border-radius: 4px;
	padding: 12px 14px;
	box-sizing: border-box;
}

.g2-print-format .g2-terms-title {
	font-weight: bold;
	color: #1551C3;
	font-size: 10px;
	text-transform: uppercase;
	letter-spacing: 0.5px;
	margin-bottom: 8px;
}

.g2-print-format .g2-terms ol,
.g2-print-format .g2-terms ul {
	margin: 0;
	padding-left: 16px;
}

.g2-print-format .g2-terms li {
	margin-bottom: 4px;
}

.g2-print-format .g2-totals-table {
	width: 100%;
	border-collapse: collapse;
}

.g2-print-format .g2-totals-table td {
	border: none;
	padding: 5px 0;
	font-size: 11px;
}

.g2-print-format .g2-totals-table .g2-total-label {
	text-align: left;
	color: #888;
	padding-right: 12px;
}

.g2-print-format .g2-totals-table .g2-total-value {
	text-align: right;
	color: #000;
	font-weight: bold;
	min-width: 90px;
}

.g2-print-format .g2-bank-details {
	flex: 0.9;
	min-width: 220px;
	margin-top: 0;
	background: #f5f5f5;
	border: 1px solid #e0e0e0;
	border-radius: 4px;
	padding: 12px 14px;
	font-size: 9px;
	color: #333;
	line-height: 1.55;
	box-sizing: border-box;
}

.g2-print-format .g2-bank-title {
	font-weight: bold;
	color: #1551C3;
	font-size: 10px;
	text-transform: uppercase;
	letter-spacing: 0.5px;
	margin-bottom: 8px;
}

.g2-print-format .g2-bank-line {
	margin-bottom: 3px;
}

.g2-print-format .g2-bank-line span {
	color: #666;
	font-weight: bold;
	margin-right: 4px;
}

.g2-print-format .g2-total-box-table {
	width: 100%;
	border-collapse: collapse;
	margin-top: 10px;
}

.g2-print-format .g2-total-box-table td {
	background-color: #1551C3;
	color: #ffffff;
	font-weight: bold;
	padding: 10px 14px;
	font-size: 12px;
	text-transform: uppercase;
	letter-spacing: 0.3px;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}

/* Pay Slip — match TUX-4 sample layout */
/* Hide Frappe Print Settings "Add Draft Heading" for this format */
[document-status="draft"],
[document-status="cancelled"] {
	display: none !important;
}

.g2-print-format.g2-pay-slip {
	font-family: Arial, Helvetica, sans-serif;
	font-size: 12px;
	color: #000;
	width: 100%;
}

.g2-print-format.g2-pay-slip .g2-content {
	width: 100%;
}

.g2-print-format.g2-pay-slip .g2-payslip-header {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
	margin: 0 0 4px;
}

.g2-print-format.g2-pay-slip .g2-payslip-logo-cell {
	width: 40%;
	vertical-align: top;
	text-align: left;
	padding: 0 12px 0 0;
}

.g2-print-format.g2-pay-slip .g2-payslip-logo {
	display: block;
	height: 64px;
	width: auto;
	max-width: 220px;
	object-fit: contain;
	object-position: left top;
}

.g2-print-format.g2-pay-slip .g2-payslip-company-cell {
	width: 60%;
	vertical-align: top;
	text-align: right;
	padding: 0 0 0 12px;
}

.g2-print-format.g2-pay-slip .g2-payslip-company-name {
	font-size: 14px;
	font-weight: bold;
	color: #000;
	margin: 0 0 4px;
	line-height: 1.3;
}

.g2-print-format.g2-pay-slip .g2-payslip-company-line {
	font-size: 11px;
	color: #000;
	line-height: 1.4;
	margin: 0;
}

.g2-print-format.g2-pay-slip .g2-payslip-title {
	display: block;
	width: 100%;
	text-align: center;
	font-size: 22px;
	font-weight: bold;
	color: #000;
	margin: 16px 0 14px;
	line-height: 1.2;
}

.g2-print-format.g2-pay-slip .g2-payslip-info,
.g2-print-format.g2-pay-slip .g2-payslip-ledger {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
	margin: 0 0 14px;
}

.g2-print-format.g2-pay-slip .g2-payslip-info td {
	width: 50%;
	padding: 8px 10px;
	border: 1px solid #000;
	font-size: 12px;
	vertical-align: middle;
	text-align: left;
	line-height: 1.35;
}

.g2-print-format.g2-pay-slip .g2-payslip-ledger th {
	width: 50%;
	background-color: #d9d9d9;
	color: #000;
	font-size: 12px;
	font-weight: bold;
	text-align: left;
	padding: 8px 10px;
	border: 1px solid #000;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}

.g2-print-format.g2-pay-slip .g2-payslip-ledger td {
	width: 50%;
	padding: 8px 10px;
	border: 1px solid #000;
	font-size: 12px;
	color: #000;
	vertical-align: top;
	text-align: left;
	line-height: 1.35;
}

.g2-print-format.g2-pay-slip .g2-payslip-total-row td {
	font-weight: bold;
}

.g2-print-format.g2-pay-slip .g2-payslip-net {
	font-size: 13px;
	margin: 2px 0 12px;
	line-height: 1.5;
	text-align: left;
}

.g2-print-format.g2-pay-slip .g2-payslip-bank {
	font-size: 12px;
	line-height: 1.7;
	margin: 0 0 36px;
	text-align: left;
}

.g2-print-format.g2-pay-slip .g2-payslip-bank-title {
	font-weight: bold;
	margin: 0 0 2px;
}

.g2-print-format.g2-pay-slip .g2-payslip-note {
	display: block;
	width: 100%;
	text-align: center;
	font-size: 11px;
	color: #000;
	margin: 28px 0 16px;
}

.g2-print-format.g2-pay-slip .g2-payslip-footer-bar {
	position: relative;
	overflow: hidden;
	width: 100%;
	box-sizing: border-box;
	background-color: #1551C3;
	color: #ffffff;
	text-align: center;
	padding: 14px 12px;
	font-size: 12px;
	font-weight: bold;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}

.g2-print-format.g2-pay-slip .g2-payslip-footer-accent {
	position: absolute;
	right: 0;
	top: 0;
	bottom: 0;
	width: 38%;
	background: linear-gradient(135deg, transparent 42%, #5b8def 42%, #7aa5f0 100%);
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}

.g2-print-format.g2-pay-slip .g2-payslip-footer-bar span {
	position: relative;
	z-index: 1;
}

/* Payment voucher */
.g2-print-format .g2-voucher-meta {
	width: 100%;
}

.g2-print-format .g2-voucher-meta .g2-meta-item {
	width: calc(50% - 10px);
}

.g2-print-format .g2-sign-row {
	display: flex;
	justify-content: space-between;
	gap: 48px;
	margin-top: 64px;
	padding: 0 8px;
}

.g2-print-format .g2-sign-box {
	flex: 1;
	max-width: 240px;
}

.g2-print-format .g2-sign-line {
	border-bottom: 1px solid #555;
	height: 42px;
	margin-bottom: 8px;
}

.g2-print-format .g2-sign-label {
	font-size: 10px;
	font-weight: bold;
	color: #1551C3;
	text-transform: uppercase;
	letter-spacing: 0.4px;
}

@media print {
	.g2-print-format .g2-items-table thead th,
	.g2-print-format .g2-items-table thead th font,
	.g2-print-format .g2-items-table thead th b {
		background-color: #1551C3 !important;
		color: #ffffff !important;
		-webkit-print-color-adjust: exact !important;
		print-color-adjust: exact !important;
	}

	.g2-print-format .g2-total-box-table td,
	.g2-print-format .g2-total-box-table td font,
	.g2-print-format .g2-total-box-table td b {
		background-color: #1551C3 !important;
		color: #ffffff !important;
		-webkit-print-color-adjust: exact !important;
		print-color-adjust: exact !important;
	}

	.g2-print-format .g2-items-table td font {
		-webkit-print-color-adjust: exact !important;
		print-color-adjust: exact !important;
	}
}

