html:
{%
	const report_columns = report
		.get_columns_for_print()
		.filter((col) => !col.hidden);

	const account_col = report_columns[0];
	const value_columns = report_columns.slice(1).filter((col) => col.fieldname !== "currency");

	function clean_name(row) {
		return String(row.account_name || row.section || "")
			.replace(/^['"]|['"]$/g, "")
			.trim();
	}

	function row_total(row) {
		if (!is_null(row.total) && row.total !== "") {
			return flt(row.total);
		}
		let sum = 0;
		for (let i = 0; i < value_columns.length; i++) {
			const col = value_columns[i];
			if (col.fieldname === "total") continue;
			if (!is_null(row[col.fieldname])) {
				sum += flt(row[col.fieldname]);
			}
		}
		return sum;
	}

	function find_revenue_base() {
		let income_root = null;
		for (let j = 0; j < data.length; j++) {
			const row = data[j];
			const name = clean_name(row);
			if (!name) continue;
			if (/^Total Income/i.test(name)) {
				return row_total(row);
			}
			if (!income_root && (name === __("Income") || name === "Income")) {
				income_root = row;
			}
		}
		return income_root ? row_total(income_root) : 0;
	}

	const revenue_base = find_revenue_base();

	function format_pnl(value) {
		if (is_null(value) || value === "") return "";
		const n = flt(value);
		if (!n && n !== 0) return "";
		const formatted = format_number(Math.abs(n), null, 2);
		if (n < 0) return "(" + formatted + ")";
		return formatted;
	}

	function format_pct(value, base) {
		if (!base) return "";
		if (is_null(value) || value === "") return "";
		const pct = (flt(value) / flt(base)) * 100;
		return format_number(pct, null, 2) + "%";
	}

	function row_class(row) {
		const name = clean_name(row);
		if (!name) return "g2-pnl-blank";

		const is_root = !(row.parent_account || row.parent_section);
		const is_total = /^Total /i.test(name);
		const is_profit =
			/Profit for the year/i.test(name) ||
			/Net Profit/i.test(name) ||
			/Gross Profit/i.test(name) ||
			/Operating Profit/i.test(name) ||
			/EBIT/i.test(name);

		if (is_profit) return "g2-pnl-profit";
		if (is_total) return "g2-pnl-total";
		if (is_root) return "g2-pnl-section";
		return "g2-pnl-line";
	}

	function period_label() {
		if (filters.filter_based_on === "Fiscal Year") {
			const from_fy = filters.from_fiscal_year || "";
			const to_fy = filters.to_fiscal_year || from_fy;
			if (from_fy && to_fy && from_fy !== to_fy) {
				return from_fy + " – " + to_fy;
			}
			return from_fy || "";
		}
		if (filters.period_start_date && filters.period_end_date) {
			return (
				frappe.datetime.str_to_user(filters.period_start_date) +
				" – " +
				frappe.datetime.str_to_user(filters.period_end_date)
			);
		}
		return "";
	}

	const company_name = filters.company || "";
	const currency =
		filters.presentation_currency ||
		(typeof erpnext !== "undefined" && erpnext.get_currency
			? erpnext.get_currency(company_name)
			: "") ||
		"";
	const fy_label =
		filters.from_fiscal_year ||
		(filters.period_start_date ? String(filters.period_start_date).slice(0, 4) : "");
	const reporting_period = period_label();
%}

