<div class="g2-monthly-pnl">
	<div class="g2-pnl-banner">
		<h1>{%= __("Monthly Profit & Loss Statement") %}</h1>
		<div class="g2-pnl-subtitle">
			{%= __("Statement of Financial Performance with Vertical % Analysis") %}
			{% if (fy_label) { %}
				| {%= __("Financial Year") %}: {%= fy_label %}
			{% } %}
		</div>
	</div>

	<div class="g2-pnl-meta">
		<div class="left">
			<div class="label">{%= __("Company Name") %}</div>
			<div class="value">{%= company_name %}</div>
		</div>
		<div class="right">
			<div class="label">{%= __("Reporting Period") %}</div>
			<div class="value">{%= reporting_period %}</div>
			<div class="note">
				({%= __("All figures in {0} | % expressed as ratio of Net Revenue / Total Income", [currency || __("Company Currency")]) %})
			</div>
		</div>
	</div>

	<table>
		<thead>
			<tr>
				<th class="col-account">{%= __("Particulars / Account") %}</th>
				{% for (let i = 0; i < value_columns.length; i++) { %}
					{% const col = value_columns[i]; %}
					<th class="col-value {%= col.fieldname === 'total' ? 'col-total' : '' %}">
						{%= col.label %}
					</th>
				{% } %}
				<th class="col-pct">{%= __("% Rev") %}</th>
			</tr>
		</thead>
		<tbody>
			{% for (let j = 0; j < data.length; j++) { %}
				{%
					const row = data[j];
					const name = clean_name(row);
					const cls = row_class(row);
					const total_val = row_total(row);
					const show_values = !!name;
				%}
				<tr class="{%= cls %}">
					<td class="col-account">
						{% if (name) { %}
							<span style="padding-left: {%= cint(row.indent) * 1.2 %}em">
								{%= name %}
							</span>
						{% } %}
					</td>
					{% for (let i = 0; i < value_columns.length; i++) { %}
						{%
							const col = value_columns[i];
							let cell_val = row[col.fieldname];
							if (col.fieldname === "total" && (is_null(cell_val) || cell_val === "") && show_values) {
								cell_val = total_val;
							}
						%}
						<td class="col-value">
							{% if (show_values && !is_null(cell_val) && cell_val !== "") { %}
								{%= format_pnl(cell_val) %}
							{% } %}
						</td>
					{% } %}
					<td class="col-pct">
						{% if (show_values && cls !== "g2-pnl-blank") { %}
							{%= format_pct(total_val, revenue_base) %}
						{% } %}
					</td>
				</tr>
			{% } %}
		</tbody>
	</table>

	<div class="g2-pnl-signatures">
		<div class="sig-block">
			<div><strong>{%= __("Prepared By") %}:</strong> {%= __("Finance / Accounting Lead") %}</div>
			<div class="sig-line"></div>
			<div class="sig-date">{%= __("Date") %}: ________________________</div>
		</div>
		<div class="sig-block">
			<div><strong>{%= __("Approved By") %}:</strong> {%= __("Chief Financial Officer / Managing Director") %}</div>
			<div class="sig-line"></div>
		</div>
	</div>
</div>

{%
	const report_columns = report
		.get_columns_for_print()
		.filter((col) => !col.hidden);

	const value_columns = report_columns.slice(1).filter((col) => col.fieldname !== "currency");
	const col_span = 2 + value_columns.length;

	function clean_name(row) {
		return String(row.account_name || row.section || "")
			.replace(/^['"]|['"]$/g, "")
			.trim();
	}

	function format_bs(value) {
		if (is_null(value) || value === "") return "";
		const n = flt(value);
		if (!n && n !== 0) return "";
		const formatted = format_number(Math.abs(n), null, 2);
		if (n < 0) return "(" + formatted + ")";
		return formatted;
	}

	function is_grand_total(name) {
		return (
			/^Total Asset/i.test(name) ||
			/^TOTAL ASSETS/i.test(name) ||
			/Total Liability and Equity/i.test(name) ||
			/Provisional Profit/i.test(name) ||
			/Profit \/ Loss \(Credit\)/i.test(name)
		);
	}

	function row_class(row) {
		const name = clean_name(row);
		if (!name) return "g2-bs-blank";

		const is_root = !(row.parent_account || row.parent_section);
		const is_total = /^Total /i.test(name) || /^TOTAL /i.test(name);

		if (is_grand_total(name)) return "g2-bs-grand";
		if (is_total) return "g2-bs-total";
		if (is_root) return "g2-bs-section";
		return "g2-bs-line";
	}

	function is_liability_or_equity_root(name) {
		return (
			name === __("Liability") ||
			name === "Liability" ||
			name === __("Equity") ||
			name === "Equity" ||
			/^Liabilit/i.test(name)
		);
	}

	function as_of_label() {
		if (filters.filter_based_on === "Date Range" && filters.period_end_date) {
			return __("As of {0}", [frappe.datetime.str_to_user(filters.period_end_date)]);
		}
		if (filters.to_fiscal_year) {
			return __("As of / Period Ended: {0}", [filters.to_fiscal_year]);
		}
		if (filters.from_fiscal_year) {
			return filters.from_fiscal_year;
		}
		return "";
	}

	const company_name = filters.company || "";
	const currency =
		filters.presentation_currency ||
		(typeof erpnext !== "undefined" && erpnext.get_currency
			? erpnext.get_currency(company_name)
			: "") ||
		"";
	const as_of = as_of_label();

	let liabilities_heading_at = -1;
	for (let j = 0; j < data.length; j++) {
		const name = clean_name(data[j]);
		if (
			name &&
			is_liability_or_equity_root(name) &&
			!(data[j].parent_account || data[j].parent_section)
		) {
			liabilities_heading_at = j;
			break;
		}
	}
%}

