<div class="g2-balance-sheet">
	<div class="g2-bs-title">{%= __("Balance Sheet") %}</div>
	<div class="g2-bs-subtitle">
		{%= __("Statement of Financial Position") %} |
		{%= __("Prepared under International Accounting Standards (IAS 1) for UAE Corporate Reporting") %}
	</div>

	<div class="g2-bs-meta">
		<div class="col left">
			<div class="label">{%= __("Company Name") %}</div>
			<div class="value">{%= company_name %}</div>
			<div class="label">{%= __("Trade License / TRN No.") %}</div>
			<div class="value underline"></div>
		</div>
		<div class="col right">
			<div class="label">{%= __("As Of / Period Ended") %}</div>
			<div class="value">{%= as_of %}</div>
			<div class="label">{%= __("Currency") %}</div>
			<div class="value">
				{%= __("Expressed in {0}, unless otherwise stated", [currency || __("Company Currency")]) %}
			</div>
		</div>
	</div>

	<div class="g2-bs-block-title first">{%= __("Assets") %}</div>

	<table>
		<thead>
			<tr>
				<th class="col-account">{%= __("Particulars / Account") %}</th>
				<th class="col-note">{%= __("Note") %}</th>
				{% for (let i = 0; i < value_columns.length; i++) { %}
					<th class="col-value">{%= value_columns[i].label %}</th>
				{% } %}
			</tr>
		</thead>
		<tbody>
			{% for (let j = 0; j < data.length; j++) { %}
				{%
					const row = data[j];
					const name = clean_name(row);
					const cls = row_class(row);
					const show_values = !!name;
				%}

				{% if (j === liabilities_heading_at) { %}
					<tr class="g2-bs-divider">
						<td colspan="{%= col_span %}">
							{%= __("Liabilities & Shareholders' Equity") %}
						</td>
					</tr>
				{% } %}

				<tr class="{%= cls %}">
					<td class="col-account">
						{% if (name) { %}
							<span style="padding-left: {%= cint(row.indent) * 1.2 %}em">
								{%= name %}
							</span>
						{% } %}
					</td>
					<td class="col-note"></td>
					{% for (let i = 0; i < value_columns.length; i++) { %}
						{%
							const col = value_columns[i];
							const cell_val = row[col.fieldname];
						%}
						<td class="col-value">
							{% if (show_values && !is_null(cell_val) && cell_val !== "") { %}
								{%= format_bs(cell_val) %}
							{% } %}
						</td>
					{% } %}
				</tr>
			{% } %}
		</tbody>
	</table>

	<div class="g2-bs-equation">
		<div class="eq-title">{%= __("Accounting Equation Verification") %}</div>
		<div class="eq-body">
			{%= __("Assets = Liabilities + Shareholders' Equity") %}<br>
			{%= __("The accompanying notes form an integral part of these financial statements.") %}
		</div>
	</div>

	<div class="g2-bs-signatures">
		<div class="sig-block">
			<div class="sig-role">{%= __("Chief Executive Officer / Managing Director") %}</div>
			<div class="sig-line"></div>
			<div class="sig-date">{%= __("Date") %}: ____________________</div>
		</div>
		<div class="sig-block">
			<div class="sig-role">{%= __("Chief Financial Officer (CFO)") %}</div>
			<div class="sig-line"></div>
			<div class="sig-date">{%= __("Date") %}: ____________________</div>
		</div>
	</div>

	<div class="g2-bs-footnote">
		{%= __("Template prepared in accordance with IAS 1 for UAE corporate reporting purposes.") %}
	</div>
</div>

