{%
	function party_list() {
		const p = filters.party;
		if (!p) return [];
		if (Array.isArray(p)) return p.filter(Boolean);
		return [p];
	}

	function party_label() {
		const parties = party_list();
		if (parties.length) return parties.join(", ");
		if (filters.party_name) return filters.party_name;
		return __("All Parties");
	}

	function party_type_label() {
		return filters.party_type || __("Party");
	}

	function currency_code() {
		return (
			filters.presentation_currency ||
			(typeof erpnext !== "undefined" && erpnext.get_currency
				? erpnext.get_currency(filters.company)
				: "") ||
			""
		);
	}

	function fmt_amt(value) {
		if (is_null(value) || value === "" || flt(value) === 0) return "";
		return format_currency(value, currency_code());
	}

	function row_class(row, i, l) {
		const is_entry = row.posting_date;
		if (is_entry) return "g2-pl-line";
		if (i === l - 1) return "g2-pl-closing";
		if (i === l - 2) return "g2-pl-total";
		return "g2-pl-opening";
	}

	const company_name = filters.company || "";
	const currency = currency_code();
	const parties = party_list();
%}

