<div class="g2-party-ledger">
	<div class="g2-pl-banner">
		<h1>{%= __("Statement of Accounts") %}</h1>
		<div class="g2-pl-subtitle">
			{%= __("Party Ledger") %}
			{% if (currency) { %}
				| {%= __("All figures in {0}", [currency]) %}
			{% } %}
		</div>
	</div>

	<div class="g2-pl-meta">
		<div class="left">
			<div class="filter-row">
				<div class="label">{%= __("Company Name") %}</div>
				<div class="value">{%= company_name %}</div>
			</div>
			<div class="filter-row">
				<div class="label">{%= party_type_label() %}</div>
				<div class="value">{%= party_label() %}</div>
				{% if (filters.tax_id) { %}
					<div class="note">{%= __("Tax ID") %}: {%= filters.tax_id %}</div>
				{% } %}
			</div>
		</div>
		<div class="right">
			<div class="filter-row">
				<div class="label">{%= __("Statement Period") %}</div>
				<div class="value">
					{%= frappe.datetime.str_to_user(filters.from_date) %}
					–
					{%= frappe.datetime.str_to_user(filters.to_date) %}
				</div>
			</div>
			{% if (filters.account && filters.account.length) { %}
				<div class="filter-row">
					<div class="label">{%= __("Account") %}</div>
					<div class="note">{%= filters.account.join(", ") %}</div>
				</div>
			{% } %}
			{% if (filters.finance_book) { %}
				<div class="filter-row">
					<div class="label">{%= __("Finance Book") %}</div>
					<div class="note">{%= filters.finance_book %}</div>
				</div>
			{% } %}
		</div>
	</div>

	<table>
		<thead>
			<tr>
				<th class="col-date">{%= __("Date") %}</th>
				<th class="col-voucher">{%= __("Voucher Details") %}</th>
				{% if (filters.show_remarks) { %}
					<th class="col-remarks">{%= __("Remarks") %}</th>
				{% } %}
				<th class="col-amt">{%= __("Debit") %}</th>
				<th class="col-amt">{%= __("Credit") %}</th>
				<th class="col-amt">{%= __("Balance") %}</th>
			</tr>
		</thead>
		<tbody>
			{% for (var i = 0, l = data.length; i < l; i++) { %}
				{%
					var row = data[i];
					var is_entry = row.posting_date;
					var is_last = i == l - 1;
					var is_second_last = i == l - 2;
					var cls = row_class(row, i, l);
				%}
				<tr class="{%= cls %}">
					<td class="col-date">
						{% if (is_entry) { %}
							{%= frappe.datetime.str_to_user(row.posting_date) %}
						{% } else if (i == 0) { %}
							{%= frappe.datetime.str_to_user(filters.from_date) %}
						{% } %}
					</td>

					<td class="col-voucher">
						{% if (is_entry) { %}
							{%= row.voucher_type %} {%= row.voucher_no %}
							{% if (!(parties.length || (filters.account && filters.account.length))) { %}
								<div class="g2-pl-sub">{%= row.party || row.account %}</div>
							{% } %}
							{% if (row.bill_no) { %}
								<div class="g2-pl-sub">
									{%= __("Supplier Invoice No") %}: {%= row.bill_no %}
								</div>
							{% } %}
						{% } else { %}
							{% if (is_second_last) { %}
								{%= __("Total") %}
							{% } else if (is_last) { %}
								{%= __("Closing [Opening + Total] ") %}
							{% } else { %}
								{%= frappe.format(row.account, {fieldtype: "Link"}) || "&nbsp;" %}
							{% } %}
						{% } %}
					</td>

					{% if (filters.show_remarks) { %}
						<td class="col-remarks">
							{% if (is_entry && row.remarks && row.remarks != "No Remarks") { %}
								{%= row.remarks %}
							{% } %}
						</td>
					{% } %}

					<td class="col-amt">
						{% if (is_entry) { %}
							{%= fmt_amt(row.debit) %}
						{% } else if (i != 0 && !is_last) { %}
							{%= row.account && fmt_amt(row.debit) %}
						{% } %}
					</td>

					<td class="col-amt">
						{% if (is_entry) { %}
							{%= fmt_amt(row.credit) %}
						{% } else if (i != 0 && !is_last) { %}
							{%= row.account && fmt_amt(row.credit) %}
						{% } %}
					</td>

					<td class="col-amt">
						{% if (is_last) { %}
							{%= format_currency(row.balance, currency) %}
							{% if (row.balance < 0) { %} Cr{% } %}
							{% if (row.balance > 0) { %} Dr{% } %}
						{% } else { %}
							{%= format_currency(row.balance, currency) %}
						{% } %}
					</td>
				</tr>
			{% } %}
		</tbody>
	</table>

	<div class="g2-pl-footer">
		{%= __("Printed on {0}", [
			frappe.datetime.str_to_user(frappe.datetime.get_datetime_as_string())
		]) %}
	</div>
</div>

{%
	function customer_display() {
		if (filters.customer) {
			for (let i = 0; i < data.length; i++) {
				if (data[i].customer_name) return data[i].customer_name;
			}
			return filters.customer;
		}
		if (filters.customer_group && filters.customer_group.length) {
			return __("Customer Group") + ": " + filters.customer_group.join(", ");
		}
		return __("All Customers");
	}

	function currency_code() {
		if (data && data.length && data[0].currency) return data[0].currency;
		return (
			(typeof erpnext !== "undefined" && erpnext.get_currency
				? erpnext.get_currency(filters.company)
				: "") ||
			""
		);
	}

	function fmt_amt(value) {
		if (is_null(value) || value === "") return "";
		return format_currency(value, currency_code());
	}

	function fmt_date(value) {
		if (!value) return "";
		return frappe.datetime.str_to_user(value);
	}

	function period_label() {
		if (filters.from_date && filters.to_date) {
			return (
				frappe.datetime.str_to_user(filters.from_date) +
				" – " +
				frappe.datetime.str_to_user(filters.to_date)
			);
		}
		if (filters.to_date) {
			return __("As on {0}", [frappe.datetime.str_to_user(filters.to_date)]);
		}
		return "";
	}

	function logo_url() {
		const path = "/assets/g2_print_formats/images/g2-logo-header-v2.png";
		if (frappe.urllib && frappe.urllib.get_full_url) {
			return frappe.urllib.get_full_url(path);
		}
		return path;
	}

	const company_name = filters.company || "";
	const currency = currency_code();
	const period = period_label();
	const customer_name = customer_display();
	const show_customer_col = !filters.customer;

	function is_data_row(row) {
		return row && !row.is_total_row;
	}

	let invoice_count = 0;
	let total_invoice = 0;
	let total_due = 0;
	for (let i = 0; i < data.length; i++) {
		if (!is_data_row(data[i])) continue;
		invoice_count += 1;
		total_invoice += flt(data[i].invoice_amount);
		total_due += flt(data[i].balance_due);
	}
%}

