{%
	function vendor_display() {
		if (filters.supplier) {
			for (let i = 0; i < data.length; i++) {
				if (data[i].vendor_name) return data[i].vendor_name;
			}
			return filters.supplier;
		}
		if (filters.supplier_group && filters.supplier_group.length) {
			return __("Supplier Group") + ": " + filters.supplier_group.join(", ");
		}
		return __("All Vendors");
	}

	function currency_code() {
		if (data && data.length && data[0].currency) return data[0].currency;
		return (
			(typeof erpnext !== "undefined" && erpnext.get_currency
				? erpnext.get_currency(filters.company)
				: "") ||
			""
		);
	}

	function fmt_amt(value) {
		if (is_null(value) || value === "") return "";
		return format_currency(value, currency_code());
	}

	function fmt_date(value) {
		if (!value) return "";
		return frappe.datetime.str_to_user(value);
	}

	function period_label() {
		if (filters.from_date && filters.to_date) {
			return (
				frappe.datetime.str_to_user(filters.from_date) +
				" – " +
				frappe.datetime.str_to_user(filters.to_date)
			);
		}
		if (filters.to_date) {
			return __("As on {0}", [frappe.datetime.str_to_user(filters.to_date)]);
		}
		return "";
	}

	function logo_url() {
		const path = "/assets/g2_print_formats/images/g2-logo-header-v2.png";
		if (frappe.urllib && frappe.urllib.get_full_url) {
			return frappe.urllib.get_full_url(path);
		}
		return path;
	}

	const company_name = filters.company || "";
	const currency = currency_code();
	const period = period_label();
	const vendor_name = vendor_display();
	const show_vendor_col = !filters.supplier;

	function is_data_row(row) {
		return row && !row.is_total_row;
	}

	let invoice_count = 0;
	let total_invoice = 0;
	let total_due = 0;
	for (let i = 0; i < data.length; i++) {
		if (!is_data_row(data[i])) continue;
		invoice_count += 1;
		total_invoice += flt(data[i].invoice_amount);
		total_due += flt(data[i].balance_due);
	}
%}

