			return filters.customer_name;
		}
		return __("All Customers");
	}

	function currency_code() {
		if (data && data.length) {
			for (let i = data.length - 1; i >= 0; i--) {
				if (data[i].currency) return data[i].currency;
			}
		}
		return (
			(typeof erpnext !== "undefined" && erpnext.get_currency
				? erpnext.get_currency(filters.company)
				: "") ||
			""
		);
	}

	function fmt_amt(value, row_currency) {
		if (is_null(value) || value === "") return "";
		return format_currency(value, row_currency || currency_code());
	}

	function fmt_date(value) {
		if (!value) return "";
		return frappe.datetime.str_to_user(value);
	}

	function logo_url() {
		const path = "/assets/g2_print_formats/images/g2-logo-header-v2.png";
		if (frappe.urllib && frappe.urllib.get_full_url) {
			return frappe.urllib.get_full_url(path);
		}
		return path;
	}

	function is_total_row(row, index) {
		return row && (row.is_total_row || index === data.length - 1);
	}

