	const currency = currency_code();
	const customer_name = customer_display();
	const show_remarks = !!filters.show_remarks;
	const report_date = filters.report_date
		? frappe.datetime.str_to_user(filters.report_date)
		: "";

	let invoice_count = 0;
	for (let i = 0; i < data.length; i++) {
		if (!is_total_row(data[i], i) && data[i].voucher_no) {
			invoice_count += 1;
		}
	}

	let ageing_ranges = [];
	let balance_row = null;
	if (filters.show_future_payments && data && data.length) {
		balance_row = data[data.length - 1];
		const start =
			report.columns && report.columns.findIndex
				? report.columns.findIndex(function (e) {
						return e.fieldname === "age";
				  })
				: -1;
		if (start >= 0 && report.columns.length >= start + 6) {
			ageing_ranges = [
				report.columns[start].label,
				report.columns[start + 1].label,
				report.columns[start + 2].label,
				report.columns[start + 3].label,
				report.columns[start + 4].label,
				report.columns[start + 5].label,
			];
		}
	}
%}

