					<div class="g2-party-name">{%= customer_name %}</div>
					{% if (company_name) { %}
						<div class="g2-party-address">
							{%= __("Company") %}: {%= company_name %}
						</div>
					{% } %}
				</div>
				<div class="g2-meta-fields">
					<div class="g2-meta-grid">
						{% if (report_date) { %}
							<div class="g2-meta-item">
								<div class="g2-meta-label">{%= __("Report Date") %}</div>
								<div class="g2-meta-value">{%= report_date %}</div>
							</div>
						{% } %}
						{% if (filters.ageing_based_on) { %}
							<div class="g2-meta-item">
								<div class="g2-meta-label">{%= __("Ageing Based On") %}</div>
								<div class="g2-meta-value">{%= filters.ageing_based_on %}</div>
							</div>
						{% } %}
						<div class="g2-meta-item">
							<div class="g2-meta-label">{%= __("Invoices") %}</div>
							<div class="g2-meta-value">{%= invoice_count %}</div>
						</div>
					</div>
				</div>
			</div>
		</div>

		<table class="g2-items-table">
			<thead>
				<tr>
					<th class="col-date">{%= __("Date") %}</th>
					<th class="col-ref">{%= __("Reference") %}</th>
					{% if (show_remarks) { %}
						<th class="col-remarks">{%= __("Remarks") %}</th>
					{% } %}
					<th class="col-age text-right">{%= __("Age (Days)") %}</th>
					<th class="col-amt text-right">{%= __("Invoiced Amount") %}</th>
					<th class="col-amt text-right">{%= __("Paid Amount") %}</th>
					<th class="col-amt text-right">{%= __("Outstanding Amount") %}</th>
				</tr>
			</thead>
			<tbody>
				{% for (var i = 0, l = data.length; i < l; i++) { %}
					{% var row = data[i]; %}
					{% var total = is_total_row(row, i); %}
					<tr class="{%= total ? "g2-oi-total" : "" %}">
						<td class="col-date">{%= total ? "" : fmt_date(row.posting_date) %}</td>
						<td class="col-ref">
							{% if (total) { %}
								{%= __("Total") %}
							{% } else { %}
								{%= row.voucher_no || "" %}
							{% } %}
						</td>
						{% if (show_remarks) { %}
							<td class="col-remarks">
								{% if (!total && row.remarks && row.remarks != "No Remarks") { %}
									{%= row.remarks %}
								{% } %}
							</td>
						{% } %}
						<td class="col-age text-right">{%= total ? "" : (row.age || "") %}</td>
						<td class="col-amt text-right">{%= fmt_amt(row.invoiced, row.currency) %}</td>
						<td class="col-amt text-right">{%= fmt_amt(row.paid, row.currency) %}</td>
						<td class="col-amt text-right">{%= fmt_amt(row.outstanding, row.currency) %}</td>
					</tr>
				{% } %}
			</tbody>
		</table>

		{% if (filters.show_future_payments && balance_row && ageing_ranges.length) { %}
			<div class="g2-ageing-wrap">
				<div class="g2-ageing-title">{%= __("Ageing Summary") %}</div>
				<table class="g2-items-table">
					<thead>
						<tr>
							<th class="col-ref"></th>
							{% for (var r = 0; r < ageing_ranges.length; r++) { %}
								<th class="col-amt text-right">{%= __(ageing_ranges[r]) %}</th>
							{% } %}
							<th class="col-amt text-right">{%= __("Total") %}</th>
						</tr>
					</thead>
					<tbody>
						<tr class="g2-oi-total">
							<td class="col-ref">{%= __("Total Outstanding") %}</td>
							<td class="col-amt text-right">{%= format_number(balance_row.age, null, 2) %}</td>
							<td class="col-amt text-right">{%= format_currency(balance_row.range1, currency) %}</td>
							<td class="col-amt text-right">{%= format_currency(balance_row.range2, currency) %}</td>
							<td class="col-amt text-right">{%= format_currency(balance_row.range3, currency) %}</td>
							<td class="col-amt text-right">{%= format_currency(balance_row.range4, currency) %}</td>
							<td class="col-amt text-right">{%= format_currency(balance_row.range5, currency) %}</td>
							<td class="col-amt text-right">{%= format_currency(flt(balance_row.outstanding), currency) %}</td>
						</tr>
					</tbody>
				</table>
			</div>
		{% } %}

		<div class="g2-print-footer">
			{%= __("Printed on {0}", [
				frappe.datetime.str_to_user(frappe.datetime.get_datetime_as_string())
			]) %}
		</div>
	</div>
</div>

