.g2-print-format .g2-terms {
	flex: 1.3;
	font-size: 9px;
	color: #333;
	line-height: 1.55;
	background: #f5f5f5;
	border: 1px solid #e0e0e0;
	border-radius: 4px;
	padding: 12px 14px;
	box-sizing: border-box;
}

.g2-print-format .g2-terms-title {
	font-weight: bold;
	color: #1551C3;
	font-size: 10px;
	text-transform: uppercase;
	letter-spacing: 0.5px;
	margin-bottom: 8px;
}

.g2-print-format .g2-terms ol,
.g2-print-format .g2-terms ul {
	margin: 0;
	padding-left: 16px;
}

.g2-print-format .g2-terms li {
	margin-bottom: 4px;
}

.g2-print-format .g2-totals-table {
	width: 100%;
	border-collapse: collapse;
}

.g2-print-format .g2-totals-table td {
	border: none;
	padding: 5px 0;
	font-size: 11px;
}

.g2-print-format .g2-totals-table .g2-total-label {
	text-align: left;
	color: #888;
	padding-right: 12px;
}

.g2-print-format .g2-totals-table .g2-total-value {
	text-align: right;
	color: #000;
	font-weight: bold;
	min-width: 90px;
}

.g2-print-format .g2-bank-details {
	flex: 0.9;
	min-width: 220px;
	margin-top: 0;
	background: #f5f5f5;
	border: 1px solid #e0e0e0;
	border-radius: 4px;
	padding: 12px 14px;
	font-size: 9px;
	color: #333;
	line-height: 1.55;
	box-sizing: border-box;
}

.g2-print-format .g2-bank-title {
	font-weight: bold;
	color: #1551C3;
	font-size: 10px;
	text-transform: uppercase;
	letter-spacing: 0.5px;
	margin-bottom: 8px;
}

.g2-print-format .g2-bank-line {
	margin-bottom: 3px;
}

.g2-print-format .g2-bank-line span {
	color: #666;
	font-weight: bold;
	margin-right: 4px;
}

.g2-print-format .g2-total-box-table {
	width: 100%;
	border-collapse: collapse;
	margin-top: 10px;
}

.g2-print-format .g2-total-box-table td {
	background-color: #1551C3;
	color: #ffffff;
	font-weight: bold;
	padding: 10px 14px;
	font-size: 12px;
	text-transform: uppercase;
	letter-spacing: 0.3px;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}

/* Pay Slip — match TUX-4 sample layout */
/* Hide Frappe Print Settings "Add Draft Heading" for this format */
[document-status="draft"],
[document-status="cancelled"] {
	display: none !important;
}

.g2-print-format.g2-pay-slip {
	font-family: Arial, Helvetica, sans-serif;
	font-size: 12px;
	color: #000;
	width: 100%;
}

.g2-print-format.g2-pay-slip .g2-content {
	width: 100%;
}

.g2-print-format.g2-pay-slip .g2-payslip-header {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
	margin: 0 0 4px;
}

.g2-print-format.g2-pay-slip .g2-payslip-logo-cell {
	width: 40%;
	vertical-align: top;
	text-align: left;
	padding: 0 12px 0 0;
}

.g2-print-format.g2-pay-slip .g2-payslip-logo {
	display: block;
	height: 64px;
	width: auto;
	max-width: 220px;
	object-fit: contain;
	object-position: left top;
}

.g2-print-format.g2-pay-slip .g2-payslip-company-cell {
	width: 60%;
	vertical-align: top;
	text-align: right;
	padding: 0 0 0 12px;
}

.g2-print-format.g2-pay-slip .g2-payslip-company-name {
	font-size: 14px;
	font-weight: bold;
	color: #000;
	margin: 0 0 4px;
	line-height: 1.3;
}

.g2-print-format.g2-pay-slip .g2-payslip-company-line {
	font-size: 11px;
	color: #000;
	line-height: 1.4;
	margin: 0;
}

.g2-print-format.g2-pay-slip .g2-payslip-title {
	display: block;
	width: 100%;
	text-align: center;
	font-size: 22px;
	font-weight: bold;
	color: #000;
	margin: 16px 0 14px;
	line-height: 1.2;
}

.g2-print-format.g2-pay-slip .g2-payslip-info,
.g2-print-format.g2-pay-slip .g2-payslip-ledger {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
	margin: 0 0 14px;
}

.g2-print-format.g2-pay-slip .g2-payslip-info td {
	width: 50%;
	padding: 8px 10px;
	border: 1px solid #000;
	font-size: 12px;
	vertical-align: middle;
	text-align: left;
	line-height: 1.35;
}

.g2-print-format.g2-pay-slip .g2-payslip-ledger th {
	width: 50%;
	background-color: #d9d9d9;
	color: #000;
	font-size: 12px;
	font-weight: bold;
	text-align: left;
	padding: 8px 10px;
	border: 1px solid #000;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}

.g2-print-format.g2-pay-slip .g2-payslip-ledger td {
	width: 50%;
	padding: 8px 10px;
	border: 1px solid #000;
	font-size: 12px;
	color: #000;
	vertical-align: top;
	text-align: left;
	line-height: 1.35;
}

.g2-print-format.g2-pay-slip .g2-payslip-total-row td {
	font-weight: bold;
}

.g2-print-format.g2-pay-slip .g2-payslip-net {
	font-size: 13px;
	margin: 2px 0 12px;
	line-height: 1.5;
	text-align: left;
}

.g2-print-format.g2-pay-slip .g2-payslip-bank {
	font-size: 12px;
	line-height: 1.7;
	margin: 0 0 36px;
	text-align: left;
}

.g2-print-format.g2-pay-slip .g2-payslip-bank-title {
	font-weight: bold;
	margin: 0 0 2px;
}

.g2-print-format.g2-pay-slip .g2-payslip-note {
	display: block;
	width: 100%;
	text-align: center;
	font-size: 11px;
	color: #000;
	margin: 28px 0 16px;
}

.g2-print-format.g2-pay-slip .g2-payslip-footer-bar {
	position: relative;
	overflow: hidden;
	width: 100%;
	box-sizing: border-box;
	background-color: #1551C3;
	color: #ffffff;
	text-align: center;
	padding: 14px 12px;
	font-size: 12px;
	font-weight: bold;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}

.g2-print-format.g2-pay-slip .g2-payslip-footer-accent {
	position: absolute;
	right: 0;
	top: 0;
	bottom: 0;
	width: 38%;
	background: linear-gradient(135deg, transparent 42%, #5b8def 42%, #7aa5f0 100%);
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}

.g2-print-format.g2-pay-slip .g2-payslip-footer-bar span {
	position: relative;
	z-index: 1;
}

/* Payment voucher */
.g2-print-format .g2-voucher-meta {
	width: 100%;
}

.g2-print-format .g2-voucher-meta .g2-meta-item {
	width: calc(50% - 10px);
}

.g2-print-format .g2-sign-row {
	display: flex;
	justify-content: space-between;
	gap: 48px;
	margin-top: 64px;
	padding: 0 8px;
}

.g2-print-format .g2-sign-box {
	flex: 1;
	max-width: 240px;
}

.g2-print-format .g2-sign-line {
	border-bottom: 1px solid #555;
	height: 42px;
	margin-bottom: 8px;
}

.g2-print-format .g2-sign-label {
	font-size: 10px;
	font-weight: bold;
	color: #1551C3;
	text-transform: uppercase;
	letter-spacing: 0.4px;
}

@media print {
	.g2-print-format .g2-items-table thead th,
	.g2-print-format .g2-items-table thead th font,
	.g2-print-format .g2-items-table thead th b {
		background-color: #1551C3 !important;
		color: #ffffff !important;
		-webkit-print-color-adjust: exact !important;
		print-color-adjust: exact !important;
	}

	.g2-print-format .g2-total-box-table td,
	.g2-print-format .g2-total-box-table td font,
	.g2-print-format .g2-total-box-table td b {
		background-color: #1551C3 !important;
		color: #ffffff !important;
		-webkit-print-color-adjust: exact !important;
		print-color-adjust: exact !important;
	}

	.g2-print-format .g2-items-table td font {
		-webkit-print-color-adjust: exact !important;
		print-color-adjust: exact !important;
	}
}
